// Prep Leads API Call for morning TOP-N call list
if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}
const envObj = (typeof env !== 'undefined' && env.get) ? env : { get: () => '' };
const topN = Math.max(1, Math.min(parseInt(envObj.get('MORNING_CALL_LIST_TOP_N') || '3', 10) || 3, 10));
const limit = Math.max(topN, Math.min(parseInt(envObj.get('MORNING_CALL_LIST_LIMIT') || '50', 10) || 50, 200));

msg.leadsPath = '/api/automation/lead-qualification';
msg.method = 'POST';
msg.topic = msg.topic || 'morning-prospecting-call-list';
msg.payload = {
    hours_back: parseInt(envObj.get('MORNING_CALL_LIST_HOURS_BACK') || '24', 10) || 24,
    hot_threshold: parseInt(envObj.get('MORNING_CALL_LIST_HOT_THRESHOLD') || '70', 10) || 70,
    warm_threshold: parseInt(envObj.get('MORNING_CALL_LIST_WARM_THRESHOLD') || '40', 10) || 40,
    high_value_bond: parseFloat(envObj.get('MORNING_CALL_LIST_HV_BOND') || '2500') || 2500,
    limit: limit
};
// Explicit fail-closed flags for downstream (no client channels)
msg._staffOnly = true;
msg._forbidClientSms = true;
msg._forbidDocusealMint = true;
node.status({fill:'blue',shape:'dot',text:'prep qualification'});
return msg;

// Morning Prospecting Call List — Brendan TOP N (staff Slack ONLY)
// FAIL-CLOSED: never Twilio, never /api/imessage/send, never DocuSeal link minting,
// never defendant/client SMS. Staff channel only.
if (global.get('SYSTEM_SHUTDOWN')) {
    node.status({fill:'red',shape:'ring',text:'SHUTDOWN'});
    return null;
}

const data = msg.payload || {};
const envObj = (typeof env !== 'undefined' && env.get) ? env : { get: () => '' };
const topN = Math.max(1, Math.min(parseInt(envObj.get('MORNING_CALL_LIST_TOP_N') || '3', 10) || 3, 10));
const channel = envObj.get('SLACK_CHANNEL_PROSPECTING')
    || global.get('SLACK_CHANNEL_LEADS')
    || '#leads';
const base = (global.get('LEADS_URL') || envObj.get('LEADS_PUBLIC_URL') || envObj.get('DASHBOARD_PUBLIC_URL') || 'https://leads.shamrockbailbonds.biz').replace(/\/$/, '');

function phoneOf(h) {
    return h.phone || h.phone_number || h.contact_phone || h.defendant_phone || '';
}
function keyOf(h) {
    return String(h.booking_number || h.name || '') + '|' + String(h.county || '');
}

const hot = Array.isArray(data.hot) ? data.hot.slice() : [];
const hv = Array.isArray(data.high_value) ? data.high_value.slice() : [];
hot.sort((a, b) => (b.lead_score || 0) - (a.lead_score || 0) || (b.bond_amount || 0) - (a.bond_amount || 0));
hv.sort((a, b) => (b.bond_amount || 0) - (a.bond_amount || 0));

const seen = {};
const ranked = [];
for (const pool of [hot, hv]) {
    for (const h of pool) {
        const k = keyOf(h);
        if (!k || seen[k]) continue;
        seen[k] = true;
        ranked.push(h);
        if (ranked.length >= topN) break;
    }
    if (ranked.length >= topN) break;
}

const nowEt = new Date().toLocaleString('en-US', { timeZone: 'America/New_York', weekday: 'short', month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
const c = data.counts || {};

if (ranked.length === 0) {
    node.status({fill:'green',shape:'ring',text:'no call targets'});
    msg.payload = {
        channel: channel,
        text: `📞 *Morning Call List* (${nowEt} ET)\n_No hot/high-value prospects in window._\nScanned: ${c.scanned || 0} · Hot: ${c.hot || 0} · HV: ${c.high_value || 0}\nCRM: ${base}\n_Staff only — zero client SMS_`
    };
    return msg;
}

const lines = ranked.map((h, i) => {
    const name = h.name || 'Unknown';
    const county = h.county || '?';
    const bond = Number(h.bond_amount || 0).toLocaleString('en-US');
    const score = h.lead_score != null ? h.lead_score : '?';
    const phone = phoneOf(h);
    const booking = h.booking_number || '';
    const phoneBit = phone ? ` · 📱 ${phone}` : ' · 📱 _n/a_';
    const bookBit = booking ? ` · \`${booking}\`` : '';
    return `${i + 1}. *${name}* — ${county} · $${bond} · score ${score}${phoneBit}${bookBit}`;
}).join('\n');

const text = [
    `📞 *Morning Prospecting Call List — TOP ${ranked.length}*`,
    `_${nowEt} ET · staff only_`,
    '',
    lines,
    '',
    `Window: ${data.window_hours || 24}h · scanned ${c.scanned || 0} · hot ${c.hot || 0} · warm ${c.warm || 0} · HV ${c.high_value || 0}`,
    `CRM: ${base}`,
    '_Fail-closed: no client SMS · no DocuSeal minting · Slack staff only_'
].join('\n');

msg.payload = { channel: channel, text: text };
msg._morningCallList = { topN: ranked.length, channel: channel, staffOnly: true };
node.status({fill:'green',shape:'dot',text:`TOP ${ranked.length} → ${channel}`});
return msg;

const channel = (typeof env !== 'undefined' && env.get && env.get('SLACK_CHANNEL_ALERTS')) || '#scraper-errors';
const detail = JSON.stringify(msg.payload || msg.error || {}).slice(0, 400);
msg.payload = {
  channel: channel,
  text: '⚠️ *Morning Prospecting Call List failed*\n' + detail + '\n_Staff alert only — no client outreach attempted_'
};
return msg;
